import{_ as t,o as l,c as i,a2 as a}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Ceph Docubetter Meeting 2020-09-05","description":"","frontmatter":{"title":"Ceph Docubetter Meeting 2020-09-05","date":"2020-09-05T00:00:00.000Z","updated":"2020-09-11T00:00:00.000Z","tags":["Ceph","文档开发","分布式存储","开发者指南"],"categories":["会议纪要"],"outline":"deep"},"headers":[],"relativePath":"posts/2020/Ceph_Docubetter_Meeting_2020-09-05.md","filePath":"posts/2020/Ceph_Docubetter_Meeting_2020-09-05.md","lastUpdated":1780460162000}'),o={name:"posts/2020/Ceph_Docubetter_Meeting_2020-09-05.md"};function r(n,e,s,p,d,g){return l(),i("div",null,[...e[0]||(e[0]=[a('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间：</strong> 2020-09-05<br><strong>参会人员：</strong> [主持人]、[参会者]</p><h4 id="主要议题" tabindex="-1">主要议题： <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题：&quot;">​</a></h4><ol><li><p><strong>hacking.rst 集成到开发者指南</strong></p><ul><li>本次会议主要讨论了将包含2300行代码的 <code>hacking.rst</code> 文档集成到开发者指南中。</li><li>在集成过程中遇到了文档构建问题，经过与 Sebastian 合作，发现提交号 4ea54664 可解决构建问题。</li></ul></li><li><p><strong>文档构建问题</strong></p><ul><li>发现了其他PR中的构建问题，特别是与 <code>prompt</code> 指令相关的问题。</li><li>计划在后续的非正式会议中进一步讨论和解决这些问题。</li></ul></li><li><p><strong>入门指南与部署指南</strong></p><ul><li>主持人对入门指南和部署指南的看法有所改变，认为部署指南更为实用。</li><li>尽管如此，仍计划推进入门指南的发布，特别是针对新手。</li></ul></li><li><p><strong>网站界面更新</strong></p><ul><li>讨论了网站 landing page 的更新，包括添加三个按钮（tracker、dev guide、install guide）。</li><li>由于 Sebastian 对按钮大小的意见，该PR目前停滞，需要进一步调整和拆分。</li></ul></li><li><p><strong>文档贡献流程优化</strong></p><ul><li>与 Brad Hubbard 讨论了如何优化从远程分支拉取、修改并推送回原分支的流程。</li><li>该流程有助于处理格式不规范但内容有价值的贡献。</li></ul></li><li><p><strong>视频教程的想法</strong></p><ul><li>提出了制作视频教程的想法，特别是针对入门指南的安装步骤。</li><li>视频长度控制在47秒，强调简洁和实用。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项： <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项：&quot;">​</a></h4><ul><li><code>hacking.rst</code> 已成功集成到开发者指南，后续可能需要进一步调整。</li><li>网站 landing page 的更新需要进一步讨论和调整按钮大小。</li><li>入门指南和部署指南的发布将继续推进。</li><li>视频教程的想法将在线下进一步讨论。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h4><ul><li>主持人将发送关于 <code>hacking.rst</code> 的邮件，鼓励更多人参与贡献。</li><li>继续解决文档构建问题，特别是与 <code>prompt</code> 指令相关的问题。</li><li>调整并拆分网站 landing page 的PR，以适应不同需求。</li><li>进一步讨论和优化视频教程的想法，确保内容简洁实用。</li></ul><p><strong>会议结束时间：</strong> [具体时间]<br><strong>下次会议时间：</strong> [具体日期]</p><p><strong>记录人：</strong> [记录人姓名]<br><strong>审核人：</strong> [审核人姓名]</p>',10)])])}const h=t(o,[["render",r]]);export{u as __pageData,h as default};
